/* Estilos para o cabeçalho da página */
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.btn {
  padding: 0.8rem 1.5rem;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 500;
  transition: background-color 0.3s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.btn-primary {
  background-color: var(--color-primary);
  color: white;
}

.btn-primary:hover {
  background-color: #5a67d8;
}

/* Estilos da Tabela */
.table-container {
  background-color: #fff;
  padding: 2rem;
  border-radius: 1rem;
  box-shadow: var(--box-shadow);
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

table thead {
  border-bottom: 2px solid #eee;
}

table th {
  padding: 1rem;
  color: var(--nav-link-color);
  font-weight: 600;
  text-transform: uppercase;
  font-size: 0.85rem;
}

table td {
  padding: 1rem;
  border-bottom: 1px solid #eee;
  color: var(--color-dark);
}

table tbody tr:last-child td {
  border-bottom: none;
}

table .actions a {
  color: var(--nav-link-color);
  margin-right: 1rem;
  font-size: 1.2rem;
}

table .actions a:hover {
  color: var(--color-primary);
}

/* Estilos do Modal */
.modal {
  display: none; /* Oculto por padrão */
  position: fixed;
  z-index: 1000;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  overflow: auto;
  background-color: rgba(0, 0, 0, 0.5);
  justify-content: center;
  align-items: center;
}

.modal-content {
  background-color: #fff;
  margin: auto;
  padding: 2rem;
  border-radius: 0.5rem;
  width: 90%;
  max-width: 500px;
  animation: slide-down 0.3s ease-out;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #eee;
  padding-bottom: 1rem;
  margin-bottom: 1.5rem;
}

.close-button {
  font-size: 2rem;
  font-weight: bold;
  border: none;
  background: none;
  cursor: pointer;
  color: #aaa;
}

.modal-form .form-group {
  margin-bottom: 1.5rem;
}

.modal-form label {
  display: block;
  margin-bottom: 0.5rem;
  font-weight: 500;
  color: var(--color-dark);
}

.modal-form input {
  width: 100%;
  padding: 0.8rem;
  border: 1px solid #ccc;
  border-radius: 0.3rem;
}

.form-actions {
  text-align: right;
  margin-top: 2rem;
}

@keyframes slide-down {
  from {
    transform: translateY(-50px);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}
